import Foundation

/// Atlas entries for the film page in Music: the page, its Watch Movie button, and the "View film" link on the album page's film panel.
enum AtlasMusicFilmPage {
    static let all: [AtlasEntry] = [
        .make("screen.music.film", .screen, "Film page", "Opens from a film or a series anywhere in Music (an album's film panel, a cast list, a person's filmography, a related film). Shows the poster, year and languages, the cast and crew, the film's soundtrack albums and songs with their singers, related films, more films by the director and more music from the composer. If the film is in your video library it also has a Watch Movie button. Music keeps playing while the page is open.",
              path: ["Music", "Film"], reach: .destination("music"), aliases: ["movie page", "film cast", "film songs", "series soundtrack", "ost", "movie soundtrack"], platforms: .mac),
        .make("control.music.filmWatchMovie", .control, "Watch Movie", "On a film page, a button that appears only when the film is in your video library. It opens the movie in your library; your music queue stays where it is, and music pauses when you press Play on the movie. If the film is not in your library the page says so and shows no button.",
              path: ["Music", "Film", "Watch Movie"], aliases: ["open the movie", "play the film", "watch the film"], platforms: .mac),
        .make("control.music.filmViewFilm", .control, "View film", "In the film panel of an album page, a link that opens the film's own page with its cast, crew, soundtrack songs and related films.",
              path: ["Music", "Film info"], aliases: ["open film page", "film details"], platforms: .mac),
        .make("control.music.filmInfoDirector", .control, "Open the director", "In the film panel of an album page, a director's name that opens their page on the director role. It is a link only when the person is known by a stable id.",
              path: ["Music", "Film info", "Director"], aliases: ["film director link"], platforms: .mac),
        .make("control.music.filmInfoComposer", .control, "Open the music director", "In the film panel of an album page, a composer's name that opens their page on the composer role, or their artist page when only the music service knows them.",
              path: ["Music", "Film info", "Composer"], aliases: ["film composer link", "music director link"], platforms: .mac),
        .make("control.music.filmInfoSinger", .control, "Open a singer", "In the film panel of an album page, a singer's name that opens their artist page. It is a link only when the album's or song's own credits name that singer with a stable id.",
              path: ["Music", "Film info", "Singers"], aliases: ["film singer link"], platforms: .mac),
        .make("control.music.filmSynopsisMore", .control, "Show more of the synopsis", "On a film page, shows the whole synopsis, or only its first lines again.",
              path: ["Music", "Film", "Synopsis"], aliases: ["read more", "full story"], platforms: .mac),
        .make("control.music.filmDubbedVersion", .control, "Open a dubbed soundtrack", "On a film page, opens the soundtrack album of a dubbed version of the film.",
              path: ["Music", "Film", "Versions"], aliases: ["dubbed songs", "other language soundtrack"], platforms: .mac),
        .make("control.music.filmTrailer", .control, "Watch the trailer", "On a film page's About tab, opens the film's official trailer in your browser. It appears only when the film's source lists one.",
              path: ["Music", "Film", "About"], aliases: ["film trailer", "teaser"], platforms: .mac),
        .make("control.music.filmPlayNext", .control, "Play the film's songs next", "In the More menu of a film page, puts the film's playable songs next in the queue without interrupting what is playing.",
              path: ["Music", "Film", "More"], aliases: ["queue film songs next", "play soundtrack next"], platforms: .mac),
        .make("control.music.filmAddToQueue", .control, "Add the film's songs to the queue", "In the More menu of a film page, adds the film's playable songs to the end of the queue.",
              path: ["Music", "Film", "More"], aliases: ["queue film songs", "queue soundtrack"], platforms: .mac),
        .make("control.music.filmRadio", .control, "Film radio", "On a film page, starts a radio from the film's songs, using the first playable song of the soundtrack as the seed.",
              path: ["Music", "Film", "Radio"], aliases: ["start radio from film", "soundtrack radio"], platforms: .mac),
        .make("control.music.filmFavourite", .control, "Like the film's songs", "On a film page, the heart likes every playable song of the film, or removes those likes when they are all liked already.",
              path: ["Music", "Film", "Favorite"], aliases: ["favorite film", "like soundtrack", "heart film"], platforms: .mac),
        .make("control.music.filmAddToPlaylist", .control, "Add the film's songs to a playlist", "On a film page, opens the playlist picker with the film's playable songs.",
              path: ["Music", "Film", "Add to playlist"], aliases: ["save soundtrack to playlist", "add film songs"], platforms: .mac),
        .make("control.music.filmShare", .control, "Share the film", "On a film page, a menu to copy a link to the film's page or open the system share picker.",
              path: ["Music", "Film", "Share"], aliases: ["share film link", "film link"], platforms: .mac),
        .make("control.music.filmShareCopyLink", .control, "Copy the film's link", "In the Share menu of a film page, copies a link that opens the film's page.",
              path: ["Music", "Film", "Share"], aliases: ["copy film link"], platforms: .mac),
        .make("control.music.filmSharePicker", .control, "Share the film with the system picker", "In the Share menu of a film page, opens the system share picker for the film's link.",
              path: ["Music", "Film", "Share"], aliases: ["share sheet film"], platforms: .mac),
        .make("control.music.filmViewInfo", .control, "View film info", "In the More menu of a film page, opens the About tab with the film's facts, companies, countries, budget and box office when known.",
              path: ["Music", "Film", "More"], aliases: ["film info menu", "about the film"], platforms: .mac),
        .make("control.music.filmVideoLink", .control, "Open a film video", "On the Videos tab of a film page, opens a trailer, teaser, clip, featurette or behind-the-scenes video in your browser. It is never played in the music player.",
              path: ["Music", "Film", "Videos"], aliases: ["official film videos", "behind the scenes video", "featurette", "film clip"], platforms: .mac),
        .make("control.music.filmCrewSearch", .control, "Search the film's crew", "On the Crew tab of a film page, filters the music department and the film crew by a person's name or by a job such as editor or costume design.",
              path: ["Music", "Film", "Crew"], aliases: ["find crew member", "filter crew"], platforms: .mac),
        .make("control.music.filmCastSeeAll", .control, "See the whole cast", "On the Overview tab of a film page, when the film has more cast than the shelf shows, opens the Cast tab with everyone.",
              path: ["Music", "Film", "Overview"], aliases: ["all cast", "full cast", "see all cast"], platforms: .mac),
        .make("control.music.filmGalleryImage", .control, "Open a film picture", "On the Gallery tab of a film page, opens one of the film's stills or posters in a larger view inside the app. Pictures have no captions.",
              path: ["Music", "Film", "Gallery"], aliases: ["film stills", "film posters", "film photos"], platforms: .mac),
        .make("control.music.filmGalleryClose", .control, "Close the picture", "In the larger view of a film picture, closes it and returns to the gallery.",
              path: ["Music", "Film", "Gallery"], aliases: ["close gallery picture"], platforms: .mac),
        .make("control.music.filmGalleryPrevious", .control, "Previous picture", "In the larger view of a film picture, shows the picture before this one. The left arrow key does the same.",
              path: ["Music", "Film", "Gallery"], aliases: ["previous still", "back picture"], platforms: .mac),
        .make("control.music.filmGalleryNext", .control, "Next picture", "In the larger view of a film picture, shows the next picture. The right arrow key does the same.",
              path: ["Music", "Film", "Gallery"], aliases: ["next still", "forward picture"], platforms: .mac),
        .make("control.music.filmCrewSearchClear", .control, "Clear the crew search", "On the Crew tab of a film page, empties the crew search so every credit shows again.",
              path: ["Music", "Film", "Crew"], aliases: ["clear crew filter"], platforms: .mac)
    ]
}
